mapper.delete:
delete from favorite
where user_id = #{userId}
  and target_type = #{targetType}
  and target_id = #{targetId}

mapper.select:
select count(1) > 0
from favorite
where user_id = #{userId}
  and target_type = #{targetType}
  and target_id = #{targetId}
    limit 1

select id, user_id, target_type, target_id, create_time
from favorite
where user_id = #{userId}

    and target_type = #{targetType}

order by create_time desc
